import{_ as e,o,c as i,ae as s}from"./chunks/framework.Dn7Y7LSn.js";const u=JSON.parse('{"title":"Real-time Monitoring","description":"","frontmatter":{},"headers":[],"relativePath":"guide/real-time-monitoring.md","filePath":"guide/real-time-monitoring.md"}'),a={name:"guide/real-time-monitoring.md"};function r(n,t,d,l,g,h){return o(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="real-time-monitoring" tabindex="-1">Real-time Monitoring <a class="header-anchor" href="#real-time-monitoring" aria-label="Permalink to &quot;Real-time Monitoring&quot;">​</a></h1><p>Orchestra monitors all your Claude Code sessions through a single dashboard with live status updates.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>When Claude Code runs, it fires hook events at key moments (tool use, completion, errors). Orchestra receives these events via HTTP and updates the dashboard in real-time.</p><h2 id="session-states" tabindex="-1">Session States <a class="header-anchor" href="#session-states" aria-label="Permalink to &quot;Session States&quot;">​</a></h2><p>Each session card shows the current state:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Running</strong></td><td>Claude is actively working (reading, writing, executing)</td></tr><tr><td><strong>Thinking</strong></td><td>Claude is processing between tool calls</td></tr><tr><td><strong>Waiting Input</strong></td><td>Claude has stopped and is waiting for your input</td></tr><tr><td><strong>Waiting Permission</strong></td><td>Claude needs permission to proceed</td></tr><tr><td><strong>Done</strong></td><td>Session has ended</td></tr></tbody></table><h2 id="activity-types" tabindex="-1">Activity Types <a class="header-anchor" href="#activity-types" aria-label="Permalink to &quot;Activity Types&quot;">​</a></h2><p>The dashboard also shows what Claude is currently doing:</p><ul><li><strong>Reading</strong> — Reading files (Read, Glob, Grep tools)</li><li><strong>Writing</strong> — Editing or creating files (Edit, Write tools)</li><li><strong>Running</strong> — Executing commands (Bash tool)</li><li><strong>Coding</strong> — Using other development tools</li><li><strong>Idle</strong> — No active tool use</li></ul><h2 id="session-cards" tabindex="-1">Session Cards <a class="header-anchor" href="#session-cards" aria-label="Permalink to &quot;Session Cards&quot;">​</a></h2><p>Each session card displays:</p><ul><li><strong>Title</strong> — Derived from the working directory name</li><li><strong>Status badge</strong> — Current session state with color coding</li><li><strong>Last activity</strong> — Most recent tool or command output</li><li><strong>Jump button</strong> — One-click navigation to the terminal session</li></ul>',13)])])}const m=e(a,[["render",r]]);export{u as __pageData,m as default};
